        new StatusHandler(HttpStatusCode.InternalServerError));

    var error = await Assert.ThrowsAsync<
        InvalidOperationException>(() =>
            StaticExporter.ExportAsync(
                broken, webRoot, output));

    Assert.Contains("500", error.Message);
}

